mapper.select:
SELECT FROM project_repo r LEFT JOIN requirement req ON req.id = r.req_id AND req.workspace_id = r.workspace_id WHERE r.workspace_id = #{workspaceId}
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = r.workspace_id AND pm.project_id = r.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
ORDER BY r.created_at, r.id
